using UnityEngine;  public class WorldQuestBox : WorldItemContainerBase, IInteractable {     [Header("QuestBox References")]     [SerializeField] private QuestBoxData questBoxDataRef;     private QuestBoxData questBoxData;      protected override IItemContainer Container => questBoxData;      public override float HoldTime => 0.3f; // 빠른 상호작용      protected override void Awake()     {         base.Awake();          if (questBoxDataRef != null)         {             questBoxData = Instantiate(questBoxDataRef);             questBoxData.InitializeWithPreset();         }     }      // 비어있어도 상호작용 가능 (autoRefill일 수 있으니까)     public override bool CanInteract() => questBoxData != null;      protected override void OnTransferComplete()     {         base.OnTransferComplete();          // 리필 처리         questBoxData.OnItemsRetrieved();          // 1회용이면 제거         if (questBoxData.IsOneTimeOnly)         {             Destroy(gameObject);         }     } }